#!/usr/bin/env python3
# generate src/elf/reloc/riscv_source.mach from the vendored RISCV.def.
#
# run by hand from anywhere: python3 vendor/llvm/gen-riscv-relocs.py
# the build never runs this. the output is deterministic. the relocation rows
# of src/elf/reloc/riscv.mach are checked against it by name and number.

import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.normpath(os.path.join(HERE, "..", ".."))
DEF = os.path.join(HERE, "RISCV.def")
OUT = os.path.join(ROOT, "src", "elf", "reloc", "riscv_source.mach")

# the numbers the psABI reserves for vendors are not relocations it defines
CUSTOM = re.compile(r"^R_RISCV_CUSTOM(\d+)$")


def fail(msg):
    sys.exit("gen-riscv-relocs: " + msg)


def main():
    text = open(DEF).read()
    rows = []
    for m in re.finditer(r"^ELF_RELOC\((\w+),\s*(\d+)\)", text, flags=re.M):
        name, value = m.group(1), int(m.group(2))
        c = CUSTOM.match(name)
        if c:
            if int(c.group(1)) != value:
                fail("custom relocation number mismatch: " + name)
            continue
        rows.append((name, value))
    if len({n for n, _ in rows}) != len(rows) or len({v for _, v in rows}) != len(rows):
        fail("a relocation name or number repeats")

    out = []
    out.append("# the relocation types of the RISC-V ELF psABI, generated by vendor/llvm/gen-riscv-relocs.py")
    out.append("# from the LLVM RISCV.def pinned in vendor/llvm/REVISION. the numbers 192 to 255 are")
    out.append("# reserved for vendors and are not listed.")
    out.append("")
    out.append("use mink.elf.tables.Constant;")
    out.append("use mink.elf.tables.Set;")
    out.append("")
    width = max(len(n) for n, _ in rows)
    for name, value in rows:
        out.append('val %s: Constant = Constant{name: "%s", value: %d, source: "RISC-V psABI"};' % (name, name, value))
    out.append("")
    out.append("val ROWS: [%d]*Constant = [%d]*Constant{" % (len(rows), len(rows)))
    for name, _ in rows:
        out.append("    ?%s," % name)
    out.append("};")
    out.append("")
    out.append("pub val SOURCE: Set = Set{count: %d, rows: ?ROWS[0]};" % len(rows))
    out.append("")
    src = "\n".join(out)
    res = subprocess.run(["mach", "fmt", "-"], input=src, capture_output=True, text=True)
    if res.returncode != 0:
        fail("mach fmt failed: " + res.stdout + res.stderr)
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w") as f:
        f.write(res.stdout)


main()
